// attrs marks the link of the current page, then adds the caller's
// attributes.
func (p SidebarMenuButtonProps) attrs() gx.Attrs {
	if !p.Active {
		return p.Attrs
	}
	return append(gx.Attrs{{Key: "aria-current", Value: "page"}}, p.Attrs...)
}

